/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { readFileSync } from 'node:fs'
import { normalize, resolve, UriError } from './uri.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function splitRecords(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

function main() {
  const args = process.argv.slice(2)
  const mode = args.length === 1 ? args[0] : null
  if (mode !== 'normalize' && mode !== 'resolve') {
    fail('usage: cli.js normalize|resolve')
  }

  const input = readFileSync(0, 'utf8')
  const records = splitRecords(input)

  const results = []
  for (let i = 0; i < records.length; i++) {
    const lineNumber = i + 1
    const record = records[i]
    try {
      if (mode === 'normalize') {
        results.push(normalize(record))
      } else {
        const spaceIdx = record.indexOf(' ')
        if (spaceIdx === -1) {
          fail(`line ${lineNumber}: expected a base and a reference`)
        }
        const base = record.slice(0, spaceIdx)
        const ref = record.slice(spaceIdx + 1)
        results.push(resolve(base, ref))
      }
    } catch (err) {
      if (err instanceof UriError) {
        fail(`line ${lineNumber}: ${err.message}`)
      }
      throw err
    }
  }

  process.stdout.write(results.length === 0 ? '' : results.join('\n') + '\n')
  process.exit(0)
}

main()
"}

